272	static std::vector<torch::Tensor> tc_dump_ff2_operands(torch::Tensor params, int64_t B) {
273	    TcScratch& sc = tc_scratch_for(params, (int)B, tc_effective_nctas(params, 4));
274	    const int T = (int)B * vit::kSeq;
275	    const int64_t d = vit::kD, dff = vit::kDff;
276	    const int Tp = (int)B * vit::kNPatch;
277	    auto acts_bf16 = sc.workspace.slice(0, 0, ::sg::fused::sm90::vit_tc_acts_floats(T, (int)B))
278	                         .view(torch::kBFloat16);
279	    // mirror vit_acts_bind: walk to dY_ff2[1] and X_gact[1].
280	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
281	    int64_t off = (int64_t)Tp * vit::kPatch;    // skip X_patch
282	    int64_t off_Xgact1 = -1, off_dYff2_1 = -1;
283	    for (int li = 0; li < vit::kLayers; ++li) {
284	        off += Td;          // X_in
285	        off += Td;          // X_ctx
286	        off += Td;          // X_x1
287	        if (li == 1) off_Xgact1 = off;
288	        off += Tff;         // X_gact
289	        off += T3d;         // dY_qkv
290	        off += Td;          // dY_a
291	        off += Tff;         // dY_ff0
292	        if (li == 1) off_dYff2_1 = off;
293	        off += Td;          // dY_ff2
294	    }
295	    auto Xgact1 = acts_bf16.slice(0, off_Xgact1, off_Xgact1 + Tff).to(torch::kFloat32).to(torch::kCPU);
296	    auto dYff2_1 = acts_bf16.slice(0, off_dYff2_1, off_dYff2_1 + Td).to(torch::kFloat32).to(torch::kCPU);
297	    return {dYff2_1, Xgact1};  // [T*d], [T*dff]
298	}
