323	
324	    static torch::Tensor s_gn, s_ga, s_gg, s_ws;
325	    static int64_t s_ws_floats = 0;
326	    const int64_t need = (int64_t)n_sms * total + n_sms + 1;
327	    if (!s_gn.defined()) {
